-- ============================================================================
-- FORGED — seed data: exercise library + workout templates extracted from your
-- PDFs. 322 unique exercises, 426 workout-day templates.
-- Run forged-schema.sql FIRST. Safe to re-run (upserts on id).
-- ============================================================================

-- ---- EXERCISE LIBRARY ----
on conflict (id) do update set name=excluded.name, category=excluded.category, muscle_group=excluded.muscle_group, equipment=excluded.equipment, tracking_type=excluded.tracking_type;

-- ---- WORKOUT TEMPLATES ----
on conflict (id) do update set name=excluded.name, plan=excluded.plan, source_client=excluded.source_client, dur=excluded.dur, equip=excluded.equip, exercises=excluded.exercises;
